// Package data contains data and information about the data files.
package data

import "time"

// ShortNewsRecording is a JSON file generated by using
// `app.ExportRecordingData()` in recorderapp package.
const (
	ShortNewsRecording         = "short_news_recording.json"
	ShortNewsRecordingDuration = 208390 * time.Millisecond
)

// ShortNewsAudio is an audio file generated by
// gtts-cli -f news.txt --output=short_news.mp3
// ffmpeg -i short_news.mp3 short_news.wav
const (
	ShortNewsAudio         = "short_news.wav"
	ShortNewsAudioDuration = 33940 * time.Millisecond
)

// ShortJapaneseNewsAudio is an audio file generated by
// gtts-cli -f japanese_news.txt --output=short_japanese_news.mp3
// ffmpeg -i short_japanese_news.mp3 short_japanese_news.wav
const (
	ShortJapaneseNewsAudio         = "short_japanese_news.wav"
	ShortJapaneseNewsAudioDuration = 44950 * time.Millisecond
)

// Input<X>KRecording is JSON files generated by using
// `app.ExportRecordingData()` in recorderapp package
// with this patch (crrev.com/c/6073605).
// X represents the audio transcription input token length.
//
//	contents come from http://shortn/_UD52wnabJu
const (
	Input1KRecording          = "input_1k_tokens_recording.json"
	Input1KRecordingDuration  = 284448 * time.Millisecond
	Input3KRecording          = "input_3k_tokens_recording.json"
	Input3KRecordingDuration  = 849792 * time.Millisecond
	Input7K5Recording         = "input_7k5_tokens_recording.json"
	Input7K5RecordingDuration = 2184024 * time.Millisecond
	Input11KRecording         = "input_11k_tokens_recording.json"
	Input11KRecordingDuration = 3134552 * time.Millisecond
)
